-- 0008_suprema_profiles.sql
-- Extração real do catálogo de perfis Tec-Vidro (fonte técnica 4), 41 perfis.
--
-- ACHADO IMPORTANTE DA EXTRAÇÃO: a palavra "Suprema" NÃO aparece em nenhuma das
-- 10 páginas do PDF. O catálogo se identifica apenas como linha "TEC-SUP" e usa o
-- prefixo "SU" nos códigos de perfil. O nome "Suprema" veio do enunciado original
-- da tarefa, não da fonte — por isso corrigimos a linha/fonte para refletir
-- honestamente essa lacuna, sem deixar de manter o nome comercial dado pelo
-- usuário como referência (campo `code` da linha continua SUPREMA para não
-- quebrar a rastreabilidade com o pedido original).
UPDATE product_lines
SET description = 'Linha identificada no catálogo como "TEC-SUP" (perfis com prefixo SU). O nome comercial "Suprema" foi usado no pedido original mas NÃO aparece escrito em nenhuma das 10 páginas do PDF-fonte — tratar como não confirmado textualmente até checar com o fabricante ou outra fonte.',
    origin_type = 'ENCONTRADO_DOCUMENTO',
    status_code = 'NECESSITA_CONFERENCIA'
WHERE id = 6;

UPDATE technical_sources
SET title = 'Catálogo de Perfis Tec-Vidro "TEC-SUP" (linha referida como Suprema no pedido original)',
    notes = 'Extração concluída: 41 perfis (P-1249 a P-1288 + P-1303 fora de sequência), 10/10 páginas lidas. Sem coluna de aplicação em nenhum perfil. Sem segmentação "revenda"/"fachada cortina" no documento (ver docs/FONTES.md). Condição comercial isolada p.9: pedido mínimo 300kg, barras de 6m — aplicabilidade (todos os perfis ou só os da página) não está clara no texto.'
WHERE id = 4;

-- Perfis (código primário = SU-xxx; código interno do fabricante P-xxxx preservado na descrição)
SET @ref_4_2 = LAST_INSERT_ID();

SET @ref_4_3 = LAST_INSERT_ID();

SET @ref_4_4 = LAST_INSERT_ID();

SET @ref_4_5 = LAST_INSERT_ID();

SET @ref_4_6 = LAST_INSERT_ID();

SET @ref_4_7 = LAST_INSERT_ID();

SET @ref_4_8 = LAST_INSERT_ID();

SET @ref_4_9 = LAST_INSERT_ID();
